// `wasm/` is generated by `npm run wasm` (crates/musette-wasm, git-ignored).
import type * as Wasm from './wasm/musette_wasm';
import type { Cc600Field, Core, DecodedFrame, ParsedRoute, RouteAnalysis } from './types';

const f64 = (a: number[]) => Float64Array.from(a);

/** The Core over the WASM build of musette-core, once initialised. */
export function wasmCore(m: typeof Wasm): Core {
  return {
    analyzeRoute: (lats, lons, eles) => m.analyzeRoute(f64(lats), f64(lons), f64(eles)) as RouteAnalysis,
    parseGpx(text) {
      const r = m.parseGpx(text) as { name: string; lats: Float64Array; lons: Float64Array; eles: Float64Array };
      return { name: r.name, lats: [...r.lats], lons: [...r.lons], eles: [...r.eles] } satisfies ParsedRoute;
    },
    verifyFit: (bytes) => m.verifyFit(bytes),
    brytonFindActivities: (paths, sizes) =>
      (m.brytonFindActivities(paths, f64(sizes)) as { id: string; size?: number | null }[]).map((a) => ({
        id: a.id,
        size: a.size ?? undefined,
      })),
    cc600Encode: (op, seq, payload) => m.cc600Encode(op, seq, payload),
    cc600Decode: (bytes) => (m.cc600Decode(bytes) as DecodedFrame | undefined) ?? undefined,
    cc600BuildRoute: (name, lats, lons, eles) => m.cc600BuildRoute(name, f64(lats), f64(lons), f64(eles)),
    cc600TransferBegin: (kind, bytes) => m.cc600TransferBegin(kind, bytes),
    cc600TransferChunk: (offset, data) => m.cc600TransferChunk(offset, data),
    cc600Sender(size) {
      const s = new m.Cc600Sender(size);
      return {
        ready: (p) => s.ready(p),
        ack: (p) => s.ack(p),
        resend: (p) => s.resend(p),
        nextChunk: (max) => {
          const c = s.nextChunk(max);
          return c ? [c[0], c[1]] : undefined;
        },
        done: () => s.done(),
        permille: () => s.permille(),
        free: () => s.free(),
      };
    },
    cc600Receiver(window, free) {
      const r = new m.Cc600Receiver(window, free);
      return {
        handle: (op, payload) => r.handle(op, payload) ?? undefined,
        disconnect: () => r.disconnect(),
        received: () => r.received(),
        committed: () => r.committed() ?? undefined,
      };
    },
    cc600SettingsFields: () =>
      (m.cc600SettingsFields() as (Omit<Cc600Field, 'min' | 'max'> & { min?: number | null; max?: number | null })[]).map(
        (f) => ({ ...f, min: f.min ?? undefined, max: f.max ?? undefined }),
      ),
    cc600SettingsParse: (text) => m.cc600SettingsParse(text) as Record<string, string>,
    cc600SettingsApply: (current, changes) => m.cc600SettingsApply(current, changes),
  };
}
